### S1: Build a comprehensive form field validator.

```python
from typing import Optional

class FieldValidator:
    """Reusable form field validation using is___() methods"""

    @staticmethod
    def required(value: str, field_name: str) -> Optional[str]:
        if not value or value.isspace():
            return f"{field_name} is required"
        return None

    @staticmethod
    def alpha_only(value: str, field_name: str) -> Optional[str]:
        clean = value.replace(" ", "").replace("-", "").replace("'", "")
        if not clean.isalpha():
            return f"{field_name} must contain only letters"
        return None

    @staticmethod
    def numeric_only(value: str, field_name: str) -> Optional[str]:
        if not value.isdecimal():
            return f"{field_name} must contain only digits (0-9)"
        return None

    @staticmethod
    def alphanumeric(value: str, field_name: str) -> Optional[str]:
        if not value.isalnum():
            return f"{field_name} must contain only letters and digits"
        return None

    @staticmethod
    def valid_identifier(value: str, field_name: str) -> Optional[str]:
        if not value.isidentifier():
            return (f"{field_name} must start with letter/underscore "
                    f"and contain only letters, digits, underscores")
        return None

    @staticmethod
    def no_whitespace(value: str, field_name: str) -> Optional[str]:
        if any(c.isspace() for c in value):
            return f"{field_name} cannot contain spaces"
        return None

    @staticmethod
    def validate(value: str, field_name: str, rules: list) -> list:
        """Run multiple validation rules, collect all errors"""
        errors = []
        for rule in rules:
            error = rule(value, field_name)
            if error:
                errors.append(error)
        return errors

# Usage
v = FieldValidator()
form_data = {
    "username":  "Veerababu_74",
    "age":       "26",
    "firstname": "John123",
    "pin":       "1234 5",
}

validations = {
    "username":  [v.required, v.valid_identifier, v.no_whitespace],
    "age":       [v.required, v.numeric_only],
    "firstname": [v.required, v.alpha_only],
    "pin":       [v.required, v.numeric_only, v.no_whitespace],
}

print("Form Validation Results:")
all_valid = True
for field, rules in validations.items():
    value  = form_data.get(field, "")
    errors = v.validate(value, field, rules)
    if errors:
        all_valid = False
        print(f"  ❌ {field}: {errors}")
    else:
        print(f"  ✅ {field}: Valid")

print(f"\nForm {'PASSED ✅' if all_valid else 'FAILED ❌'}")
```

### S2: Classify text content using `is___()` methods.

```python
def classify_string(s):
    """Classify what a string represents"""
    if not s:
        return "empty"

    if s.isdecimal():
        return f"integer ({int(s):,})"

    if s.replace(".", "", 1).replace("-", "", 1).isdecimal():
        try:
            float(s)
            return f"float ({float(s)})"
        except ValueError:
            pass

    if s.isalpha():
        if s.isupper():    return "word (ALL CAPS)"
        if s.islower():    return "word (all lowercase)"
        if s.istitle():    return "word (Title Case)"
        return "word (mixed case)"

    if s.isalnum():
        return "alphanumeric (no spaces/symbols)"

    if s.isspace():
        return f"whitespace ({len(s)} chars)"

    if s.isidentifier():
        return "valid Python identifier"

    if "@" in s and "." in s:
        return "possible email"

    if s.startswith(("http://", "https://")):
        return "URL"

    # Count character types
    digits  = sum(1 for c in s if c.isdigit())
    letters = sum(1 for c in s if c.isalpha())
    spaces  = sum(1 for c in s if c.isspace())
    special = len(s) - digits - letters - spaces

    return (f"mixed string "
            f"(letters={letters}, digits={digits}, "
            f"spaces={spaces}, special={special})")

test_strings = [
    "12345", "3.14", "-42", "hello", "HELLO",
    "Hello", "hello123", "   ", "my_var",
    "user@example.com", "https://python.org",
    "Hello, World! 2026"
]

for s in test_strings:
    print(f"  '{s}' → {classify_string(s)}")
