# S3: CSV data type inference using is___() methods
def infer_column_types(csv_text):
    """Detect data types in CSV columns"""
    lines   = csv_text.strip().split('\n')
    headers = lines[0].split(',')
    rows    = [line.split(',') for line in lines[1:]]

    column_types = {}
    for col_idx, header in enumerate(headers):
        values = [row[col_idx].strip() for row in rows if col_idx < len(row)]
        values = [v for v in values if v]  # Remove empty

        if all(v.isdecimal() for v in values):
            col_type = "integer"
        elif all(v.replace('.','',1).replace('-','',1).isdecimal() for v in values):
            col_type = "float"
        elif all(v.isalpha() for v in values):
            col_type = "text (alpha)"
        elif all(v.lower() in ('true','false','yes','no','1','0') for v in values):
            col_type = "boolean"
        else:
            col_type = "mixed/string"

        column_types[header.strip()] = {
            "type": col_type, "count": len(values),
            "sample": values[0] if values else ""
        }
    return column_types

csv_data = """name,age,salary,active,city
Alice,28,85000,True,Hyderabad
Bob,35,72000,False,Mumbai
Veerababu,26,91000,True,Hyderabad"""

types = infer_column_types(csv_data)
print("Inferred Column Types:")
for col, info in types.items():
    print(f"  {col:<12}: {info['type']:<20} (e.g., '{info['sample']}')")

# S4: Code syntax checker using isidentifier
def check_python_names(code_text):
    """Identify valid/invalid variable names in pseudocode"""
    import keyword
    issues = []
    for line in code_text.split('\n'):
        line = line.strip()
        if '=' in line:
            var_name = line.split('=')[0].strip()
            if not var_name.isidentifier():
                issues.append(f"Invalid name: '{var_name}'")
            elif keyword.iskeyword(var_name):
                issues.append(f"Reserved keyword: '{var_name}'")
    return issues

pseudocode = """
my_var = 10
2bad_name = 20
valid_name = 30
for = 40
user-name = 50
_private = 60
"""
problems = check_python_names(pseudocode)
print("\nCode Issues Found:")
for issue in problems:
    print(f"  ⚠️  {issue}")
